// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    function setUp() public {
        c = new W_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        // Admissible domain: nonzero actor, amount in a range that can satisfy MinSum
        vm.assume(actor != address(0));
        amount = bound(amount, 1 ether, 10 ether);

        // Deploy a failing callee that always reverts, so the external call fails.
        // This exposes the mutant's pre-call zeroing: acc.balance becomes 0 before the call,
        // and since the call fails, the sub_uint256(acc.balance, _am) is never executed.
        Reverter rev = new Reverter();

        // Give the actor funds and record their pre-balance
        vm.deal(actor, 20 ether);

        // Deposit into C as the actor with a future unlock time so Collect is allowed
        vm.prank(actor);
        c.Put{value: amount}(block.timestamp + 1);

        // Advance time so block.timestamp > unlockTime
        vm.warp(block.timestamp + 2);

        (uint256 preUnlock, uint256 preBalance) = c.Acc(actor);
        uint256 preCBalance = address(c).balance;

        // Route the Collect through the actor; the external call will go to rev (which reverts)
        // But c.Collect sends value to msg.sender, not to an arbitrary callee.
        // To make the external call fail, we need msg.sender to be a contract that reverts on receive.
        // So we prank as the Reverter contract itself, but then Put must also be done by it.
        // Re-do setup with the Reverter as the actor.
        // Reset: deploy a fresh C for a clean state
        W_WALLET c2 = new W_WALLET(address(new Log()));
        Reverter rev2 = new Reverter();
        vm.deal(address(rev2), 20 ether);

        // Put from rev2
        vm.prank(address(rev2));
        c2.Put{value: amount}(block.timestamp + 1);

        // Warp
        vm.warp(block.timestamp + 2);

        (uint256 preUnlock2, uint256 preBalance2) = c2.Acc(address(rev2));
        uint256 preC2Balance = address(c2).balance;

        // Collect: the call to msg.sender (rev2) will revert because rev2 has no receive and fallback reverts.
        // The reference should leave balance unchanged (the if (_s) guard fails).
        // The mutant would have already set acc.balance = 0 before the call.
        vm.prank(address(rev2));
        (bool success, ) = address(c2).call(abi.encodeWithSignature("Collect(uint256)", amount));
        success; // silence unused

        (uint256 postUnlock2, uint256 postBalance2) = c2.Acc(address(rev2));
        uint256 postC2Balance = address(c2).balance;

        // General rule: after a failed external call, the recorded balance must be unchanged
        // (or at least not zeroed), and the contract's ether balance must be unchanged.
        // The reference satisfies this; the mutant zeroes the balance before the call.
        assertTrue(postBalance2 == preBalance2 && postC2Balance == preC2Balance);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
